import * as path from "path";
import { fileURLToPath } from "url";

import type { Position } from "./layout";
import {
  combineConditions,
  sortConditions,
  type Condition,
  type ProcessGraph
} from "./processGraph";
import type { ScriptStructure } from "./structure";

/** The input of MetroFlow, as generated by BioFlow-Insight. */
export interface MetroMap {
  nodes: {
    id: string;
    name: string;
    condition?: string;
    position: { x: string; y: string };
    code: string;
    file_ref: string;
  }[];
  edges: { A: string; B: string; condition?: string; id: string }[];
  subworkflows: Record<
    string,
    {
      nodes: string[];
      label: string;
      code: string;
      condition?: string;
      file_ref: string;
    }
  >;
}

/** Where the code and the conditions of a station or a subworkflow are. */
export interface SourceRef {
  uri: string;
  kind: "process" | "workflow";
  /** The name of the process or the workflow where it is defined. */
  name: string;
  code: string;
  /** In the order of its combined condition, outermost first. */
  conditions: Condition[];
}

/** The sources of the stations (by id) and subworkflows (by key). */
export interface MetroMapSources {
  stations: Record<string, SourceRef>;
  subworkflows: Record<string, SourceRef>;
}

const byId = (a: { id: string }, b: { id: string }) =>
  a.id < b.id ? -1 : a.id > b.id ? 1 : 0;

/**
 * Builds the metro map of a process graph: a station for each process call,
 * a line for each connection, and a subworkflow for each workflow call.
 * `baseDir` is the directory that the file references are relative to.
 */
export function buildMetroMapJson(
  graph: ProcessGraph,
  positions: Map<string, Position>,
  structures: Map<string, ScriptStructure>,
  baseDir: string
): { map: MetroMap; sources: MetroMapSources } {
  const fileRef = (uri: string) => {
    let file: string;
    try {
      file = fileURLToPath(uri);
    } catch {
      file = uri;
    }
    return `(${path.relative(baseDir, file).split(path.sep).join("/")})`;
  };

  // the conditions that apply to more processes are the outermost ones
  const population = new Map<string, number>();
  for (const p of graph.processes) {
    for (const condition of new Set(p.conditions.map((c) => c.text))) {
      population.set(condition, (population.get(condition) ?? 0) + 1);
    }
  }

  // ids are the path of the station in its subworkflows, made unique
  const ids = new Map<string, string>();
  const used = new Set<string>();
  for (const p of graph.processes) {
    let id = [...p.groupPath, p.alias].join(".");
    while (used.has(id)) {
      id += "1";
    }
    used.add(id);
    ids.set(p.key, id);
  }

  const sources: MetroMapSources = { stations: {}, subworkflows: {} };
  const conditions = new Map<string, string | undefined>();
  const nodes: MetroMap["nodes"] = graph.processes.map((p) => {
    const condition = combineConditions(p.conditions, population);
    conditions.set(p.key, condition);
    const position = positions.get(p.key) ?? { x: 0, y: 0 };
    const code =
      structures.get(p.uri)?.processes.find((d) => d.name === p.definition)
        ?.code ?? "";
    sources.stations[ids.get(p.key)!] = {
      uri: p.uri,
      kind: p.kind,
      name: p.definition,
      code,
      conditions: sortConditions(p.conditions, population)
    };
    return {
      id: ids.get(p.key)!,
      name: p.alias,
      ...(condition !== undefined && { condition }),
      position: {
        x: String(position.x),
        y: String(position.y)
      },
      code,
      file_ref: fileRef(p.uri)
    };
  });

  // a line has the condition of the station that it starts from
  const edges: MetroMap["edges"] = graph.edges.map(([a, b]) => {
    const A = ids.get(a)!;
    const B = ids.get(b)!;
    const condition = conditions.get(a);
    return {
      A,
      B,
      ...(condition !== undefined && { condition }),
      id: `${A} -> ${B}`
    };
  });

  const subworkflows: MetroMap["subworkflows"] = {};
  for (const w of graph.workflows) {
    const members = graph.processes
      .filter((p) => w.path.every((key, i) => p.groupPath[i] === key))
      .map((p) => ids.get(p.key)!);
    if (members.length === 0) {
      continue;
    }
    const condition = combineConditions(w.conditions, population);
    const code =
      structures.get(w.uri)?.workflows.find((d) => d.name === w.definition)
        ?.code ?? "";
    sources.subworkflows[w.path.join(".")] = {
      uri: w.uri,
      kind: "workflow",
      name: w.definition,
      code,
      conditions: sortConditions(w.conditions, population)
    };
    subworkflows[w.path.join(".")] = {
      nodes: members,
      label: w.alias,
      code,
      ...(condition !== undefined && { condition }),
      file_ref: fileRef(w.uri)
    };
  }

  nodes.sort(byId);
  edges.sort(byId);
  return { map: { nodes, edges, subworkflows }, sources };
}
